"""Multimodal AI Companion Robot (ESP32)"""
from espzero import WiFi, OLED, I2SMic, vision, audio, esp_led
from time import sleep

WiFi().connect("YOUR_WIFI_SSID", "YOUR_WIFI_PASSWORD")

oled = OLED(scl=47, sda=21)
mic = I2SMic()

vision.start_wifi_stream(port=8080)         # Video stream
audio.start_wifi_stream(mic=mic, port=8081) # Audio stream
oled.show_face("normal")

while True:
    if "__pc_ai_data" in globals() and __pc_ai_data.get("detected"):
        oled.look_at(__pc_ai_data["hand_x"], __pc_ai_data["hand_y"], emotion="happy")
        esp_led.color = "green"

    action = (audio.get_ai_result().get("action") or "").upper()
    if action in ("HAPPY", "SURPRISED", "LOVE"):
        oled.show_face(action.lower())
        sleep(0.5)

    sleep(0.05)
